#[test]
fn unshare_copies_shared_table_and_solo_is_noop() {
    let mut pipes: PipeSpace<4, 8, 4> = PipeSpace::new();
    let id = pipes.create_pipe(1, 0, 1, false).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    // solo task: unshare must be a no-op (no extra retain, fds intact)
    pipes.unshare(1).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    assert!(pipes.lookup(1, 0).is_some());
    // share with task 2, then unshare task 1: private copy keeps both ends
    pipes.share(2, 1).unwrap();
    pipes.unshare(1).unwrap();
    assert!(pipes.lookup(1, 0).is_some());
    assert!(pipes.lookup(1, 1).is_some());
    assert_eq!(pipes.pipe_ends(id), 4);
    // task 2 still shares the original table; closing its ends frees only its refs
    pipes.close(2, 0).unwrap();
    pipes.close(2, 1).unwrap();
    assert_eq!(pipes.pipe_ends(id), 2);
    assert!(pipes.lookup(1, 0).is_some());
    // unknown task: Ok, nothing allocated
    pipes.unshare(99).unwrap();
    assert_eq!(pipes.task_fds(99), 0);
}

#[test]
fn remove_busy_only_for_active_children_not_inactive_slots() {
    let mut cg: CgroupFs<4> = CgroupFs::new();
    cg.create(b"/a.slice", 0).unwrap();
    cg.create(b"/a.slice/child", 0).unwrap();
    // active child blocks parent removal (Busy), even with zero members
    assert_eq!(cg.remove(b"/a.slice", 0), Err(ViewError::Busy));
    // leaf with no children and no members removes cleanly
    cg.remove(b"/a.slice/child", 0).unwrap();
    cg.remove(b"/a.slice", 0).unwrap();
    // freed slots are inactive: must not block re-creation or sibling removal
    cg.create(b"/b.slice", 0).unwrap();
    cg.create(b"/b.slice/kid", 0).unwrap();
    cg.remove(b"/b.slice/kid", 0).unwrap();
    cg.remove(b"/b.slice", 0).unwrap();
    // root is never removable; non-root uid denied
    assert_eq!(cg.remove(b"/", 0), Err(ViewError::PermissionDenied));
    cg.create(b"/c.slice", 0).unwrap();
    assert_eq!(cg.remove(b"/c.slice", 1000), Err(ViewError::PermissionDenied));
    cg.remove(b"/c.slice", 0).unwrap();
}

#[test]
fn override_arms_apply_values_and_reject_unknown() {
    let mut c = InstanceConfig::parse(VALID.as_bytes()).unwrap();
    c.apply_override(b"instance.workdir", b"\"/work\"").unwrap();
    assert_eq!(c.workdir.as_bytes(), b"/work");
    c.apply_override(b"instance.environment", b"[\"A=1\"]").unwrap();
    assert_eq!(c.environment.as_slice().len(), 1);
    c.apply_override(b"contract.syscalls.control", b"\"selective\"").unwrap();
    assert_eq!(c.dispatch_mode, DispatchMode::Selective);
    // catalog is pinned to the compiled CATALOG_VERSION: valid re-set ok, wrong version rejected
    c.apply_override(b"contract.catalog", b"2").unwrap();
    assert_eq!(c.contract_catalog_version, 2);
    assert!(c.apply_override(b"contract.catalog", b"3").is_err());
    assert_eq!(c.contract_catalog_version, 2);
    assert!(c.apply_override(b"no.such.key", b"\"x\"").is_err());
    assert!(c.apply_override(b"contract.digest", b"\"x\"").is_err());
}

#[test]
fn select_manifest_requires_linux_amd64_no_variant() {
    let good = serde_json::json!({"manifests":[{"mediaType":"application/vnd.oci.image.manifest.v1+json","digest":"sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","size":1,"platform":{"os":"linux","architecture":"amd64"}}]});
    assert!(select_manifest(&good).unwrap().is_some());
    // wrong OS must not be selected even if arch matches
    let bad_os = serde_json::json!({"manifests":[{"mediaType":"application/vnd.oci.image.manifest.v1+json","digest":"sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","size":1,"platform":{"os":"windows","architecture":"amd64"}}]});
    assert!(select_manifest(&bad_os).is_err());
    // wrong arch must not be selected even if os matches
    let bad_arch = serde_json::json!({"manifests":[{"mediaType":"application/vnd.oci.image.manifest.v1+json","digest":"sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","size":1,"platform":{"os":"linux","architecture":"arm64"}}]});
    assert!(select_manifest(&bad_arch).is_err());
    // non-empty variant must not match the plain amd64 slot
    let variant = serde_json::json!({"manifests":[{"mediaType":"application/vnd.oci.image.manifest.v1+json","digest":"sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa","size":1,"platform":{"os":"linux","architecture":"amd64","variant":"v8"}}]});
    assert!(select_manifest(&variant).is_err());
}

#[test]
fn decode_record_accepts_exact_path_and_link_bounds() {
    let mut buf = [0u8; HEADER_SIZE + RECORD_SIZE];
    encode_header(1, (&mut buf[..HEADER_SIZE]).try_into().unwrap());
    {
        let rec = &mut buf[HEADER_SIZE..];
        rec[2] = 3; // symlink
        rec[0..2].copy_from_slice(&(MAX_PATH as u16).to_le_bytes());
        rec[32..34].copy_from_slice(&(MAX_LINK as u16).to_le_bytes());
        rec[40] = b'/';
        for b in &mut rec[41..40 + MAX_PATH] { *b = b'a'; }
        for b in &mut rec[40 + MAX_PATH..40 + MAX_PATH + MAX_LINK] { *b = b'b'; }
    }
    // exact MAX_PATH path and MAX_LINK link must decode (boundary inclusive)
    assert!(Index::new(&buf).is_ok());
    {
        let rec = &mut buf[HEADER_SIZE..];
        rec[32..34].copy_from_slice(&((MAX_LINK + 1) as u16).to_le_bytes());
    }
    // one past MAX_LINK must be rejected at decode time
    assert_eq!(Index::new(&buf).err(), Some(VfsError::InvalidIndex));
    {
        let rec = &mut buf[HEADER_SIZE..];
        rec[32..34].copy_from_slice(&(MAX_LINK as u16).to_le_bytes());
        rec[0..2].copy_from_slice(&0u16.to_le_bytes());
    }
    // zero-length path rejected
    assert_eq!(Index::new(&buf).err(), Some(VfsError::InvalidIndex));
}

#[test]
fn human_size_scales_units_and_caps_at_gib() {
    assert_eq!(human_size(0), "0 B");
    assert_eq!(human_size(512), "512 B");
    assert_eq!(human_size(1024), "1.0 KiB");
    assert_eq!(human_size(1536), "1.5 KiB");
    assert_eq!(human_size(1024 * 1024), "1.0 MiB");
    assert_eq!(human_size(1024 * 1024 * 1024), "1.0 GiB");
    // beyond GiB stays in GiB (unit cap)
    assert_eq!(human_size(2 * 1024 * 1024 * 1024), "2.0 GiB");
}

#[test]
fn event_poll_add_rejects_zero_invalid_and_duplicate() {
    let mut poll: EventPoll<4> = EventPoll::new();
    // descriptor 0 rejected even with valid events
    assert_eq!(poll.add(0, EVENT_READ), Err(ProcessError::InvalidEvent));
    // zero events rejected even with valid descriptor
    assert_eq!(poll.add(5, 0), Err(ProcessError::InvalidEvent));
    // unsupported high bit rejected
    assert_eq!(poll.add(5, EVENT_READ | 0x80), Err(ProcessError::InvalidEvent));
    // valid single-bit and combined accepted
    poll.add(5, EVENT_READ).unwrap();
    poll.add(6, EVENT_READ | EVENT_WRITE).unwrap();
    // duplicate active descriptor rejected
    assert_eq!(poll.add(5, EVENT_WRITE), Err(ProcessError::InvalidEvent));
    // removed slot can be re-added
    poll.remove(5).unwrap();
    poll.add(5, EVENT_WRITE).unwrap();
}

#[test]
fn parse_controllers_accumulates_and_skips_empty_tokens() {
    // single controller
    assert_eq!(parse_controllers(b"+cpu"), Ok(CPU));
    // multiple controllers accumulate via OR
    assert_eq!(parse_controllers(b"+cpu +memory"), Ok(CPU | MEMORY));
    assert_eq!(parse_controllers(b"+cpu +memory +pids"), Ok(CPU | MEMORY | PIDS));
    // trailing/double spaces produce empty tokens that must be skipped, not error
    assert_eq!(parse_controllers(b"+cpu "), Ok(CPU));
    assert_eq!(parse_controllers(b"+cpu  +pids"), Ok(CPU | PIDS));
    // unknown token rejected
    assert_eq!(parse_controllers(b"+io"), Err(ViewError::PermissionDenied));
    // empty input yields zero controllers
    assert_eq!(parse_controllers(b""), Ok(0));
}

